	public static function has(string $name): bool
	{
		return isset(self::ICONS[$name]);
	}

	/** @return list<string> */
	public static function names(): array
	{
		return array_keys(self::ICONS);
	}

	/**
	 * Inline SVG markup for a named icon. Decorative by default — icon-only
	 * controls must carry aria-label on the host element.
	 */
	public static function render(string $name, string $class = 'nw-icon'): string
	{
		$body = self::ICONS[$name] ?? self::ICONS['layout-grid'];
		return '<svg class="' . htmlspecialchars($class, ENT_QUOTES) . '" aria-hidden="true" focusable="false"'
			. ' width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor"'
			. ' stroke-width="2" stroke-linecap="round" stroke-linejoin="round">' . $body . '</svg>';
	}
}
